export function ColorByIndex(index: number) {
  const colors = [
    'var(--bgColor-accent-emphasis)',
    'var(--bgColor-success-emphasis)',
    'var(--borderColor-danger-emphasis)',
    'var(--bgColor-done-emphasis)',
  ]
  return colors[index % colors.length]
}

try{ ColorByIndex.displayName ||= 'ColorByIndex' } catch {}